import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.1lR7qgqY.js";const p=JSON.parse('{"title":"第 1 章 使用說明與自我檢測","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"intro/01-usage.md","lastUpdated":1793001879000}'),o={name:"index.md"};function h(i,t,l,c,n,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="第-1-章-使用說明與自我檢測" tabindex="-1">第 1 章 使用說明與自我檢測 <a class="header-anchor" href="#第-1-章-使用說明與自我檢測" aria-label="Permalink to &quot;第 1 章 使用說明與自我檢測&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 1.3 節的硬體查詢指令未實機驗證; 硬體等級 E, F 的規格門檻待第 7 章定義</li></ul></div><p><strong>結論</strong>: 回答三個問題, 就能找到自己的閱讀路徑: 想做什麼, 手上是什麼硬體, 之後誰維運. 多數讀者只需要讀「必要」章節, 加上一至兩個依情境才讀的章節.</p><p>本手冊整理如何在自己的機器或機房內執行 AI 模型, 範圍涵蓋概念, 評估選擇, 架設部署, 應用擴充, 訓練微調與維運更新. 手冊不預設地端優於雲端, 也不包含法規解讀; 涉及法規的決定, 請洽法律顧問.</p><h2 id="_1-1-先回答三個問題" tabindex="-1">1.1 先回答三個問題 <a class="header-anchor" href="#_1-1-先回答三個問題" aria-label="Permalink to &quot;1.1 先回答三個問題&quot;">​</a></h2><table tabindex="0"><thead><tr><th>問題</th><th>選項</th></tr></thead><tbody><tr><td>1. 想做什麼</td><td>a. 自己用, 與模型對話 / b. 讓模型回答自己的文件 / c. 給 2 人以上共用 / d. 想訓練或微調 / e. 還在評估該不該自架</td></tr><tr><td>2. 手上是什麼硬體</td><td>見 1.3 節, 對應等級 A 至 F</td></tr><tr><td>3. 之後誰維運</td><td>有人每週檢查安全公告與備份 / 沒有固定的人</td></tr></tbody></table><p>第 3 題的答案會限制可選的架構: 沒有人固定維運時, 請只採用最小組合 (第 9.1 節), 並在第 3 章分層圖中只保留 ● 必要層.</p><h2 id="_1-2-依目的選閱讀路徑" tabindex="-1">1.2 依目的選閱讀路徑 <a class="header-anchor" href="#_1-2-依目的選閱讀路徑" aria-label="Permalink to &quot;1.2 依目的選閱讀路徑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>建議順序</th><th>說明</th></tr></thead><tbody><tr><td>a. 自己用</td><td>第 3 章 → 第 5, 7 章 → 第 8 章 → 第 9.1 節 → 第 18, 19 章</td><td>先確認硬體跑得動模型, 再依最小組合架設</td></tr><tr><td>b. 問自己的文件</td><td>上列路徑 → 第 12 章 → 第 14 章</td><td>檢索增強生成 (RAG) 的品質取決於文件解析與嵌入模型, 需要自建測試題</td></tr><tr><td>c. 多人共用</td><td>第 3 章 → 第 9.2 節 → 第 10, 11 章 → 第 18 至 20 章</td><td>重點在帳號, 網路隔離與備份; 閘道依第 10.1 節條件才加</td></tr><tr><td>d. 訓練或微調</td><td>第 15 章 (先判斷是否需要) → 第 16 章</td><td>多數需求用提示與檢索即可, 見第 15 章</td></tr><tr><td>e. 評估該不該自架</td><td>「決策參考」整組頁面</td><td>見 1.4 節</td></tr></tbody></table><h2 id="_1-3-硬體自我檢測" tabindex="-1">1.3 硬體自我檢測 <a class="header-anchor" href="#_1-3-硬體自我檢測" aria-label="Permalink to &quot;1.3 硬體自我檢測&quot;">​</a></h2><h3 id="查出自己的規格" tabindex="-1">查出自己的規格 <a class="header-anchor" href="#查出自己的規格" aria-label="Permalink to &quot;查出自己的規格&quot;">​</a></h3><p>以下指令未實機驗證, 輸出欄位名稱會因作業系統版本而異; 若與說明不符, 以系統設定畫面為準.</p><table tabindex="0"><thead><tr><th>系統</th><th>指令</th><th>看什麼</th></tr></thead><tbody><tr><td>Windows 或 Linux, 有 NVIDIA 顯示卡</td><td><code>nvidia-smi --query-gpu=name,memory.total,driver_version --format=csv</code></td><td>顯示卡型號, 顯示記憶體, 驅動版本</td></tr><tr><td>macOS</td><td><code>system_profiler SPHardwareDataType</code></td><td>晶片 (是否為 Apple Silicon) 與記憶體</td></tr><tr><td>Linux</td><td><code>free -h</code></td><td>系統記憶體</td></tr><tr><td>Windows (PowerShell)</td><td><code>Get-CimInstance Win32_ComputerSystem | Select-Object TotalPhysicalMemory</code></td><td>系統記憶體 (單位為位元組)</td></tr></tbody></table><h3 id="對應等級" tabindex="-1">對應等級 <a class="header-anchor" href="#對應等級" aria-label="Permalink to &quot;對應等級&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等級</th><th>特徵</th><th>建議起點</th></tr></thead><tbody><tr><td>A</td><td>無獨立顯示卡的筆電</td><td>最小組合, 桌面版介面 (第 9.4 節)</td></tr><tr><td>B</td><td>8 至 12GB 顯示記憶體</td><td>最小組合</td></tr><tr><td>C</td><td>Apple Silicon Mac, 以統一記憶體容量決定能力</td><td>16GB 用最小組合; 32GB 以上可考慮標準組合</td></tr><tr><td>D</td><td>16GB 顯示記憶體</td><td>標準組合</td></tr><tr><td>E</td><td>預算較高的單機配置</td><td>標準組合 (規格門檻待第 7 章定義)</td></tr><tr><td>F</td><td>預算更高的多卡或大容量配置</td><td>進階組合 (須有人每週維運)</td></tr></tbody></table><p>顯示記憶體 (或統一記憶體) 比運算速度更常決定「模型跑不跑得起來」, 估算方法見第 5 章. 此對應表來自研究 1 的分級, 待以第一手報價與規格核對 (信心: 中).</p><h2 id="_1-4-決策者-先看這幾頁" tabindex="-1">1.4 決策者: 先看這幾頁 <a class="header-anchor" href="#_1-4-決策者-先看這幾頁" aria-label="Permalink to &quot;1.4 決策者: 先看這幾頁&quot;">​</a></h2><p>不需要先懂技術, 也能判斷該不該自架. 建議順序如下:</p><ol><li><a href="/docs-handbook-poc/decide/summary">一頁決策摘要</a>: 三分鐘看完結論與前提.</li><li><a href="/docs-handbook-poc/decide/should-self-host">該不該自架決策樹</a>: 依資料敏感度, 使用人數與維運能力判斷.</li><li><a href="/docs-handbook-poc/decide/tco">成本試算表</a>: 自己填入數字, 比較自架與雲端 API.</li><li><a href="/docs-handbook-poc/decide/risk-checklist">風險自評</a>: 十個問題, 看維運前提是否成立.</li><li><a href="/docs-handbook-poc/decide/license-flags">授權紅旗</a>: 對外提供服務前, 哪些授權條款要先處理.</li><li><a href="/docs-handbook-poc/decide/poc-30days">30 天 PoC 計畫</a>: 用最小代價驗證, 再決定是否投入.</li></ol><h2 id="_1-5-標示的讀法" tabindex="-1">1.5 標示的讀法 <a class="header-anchor" href="#_1-5-標示的讀法" aria-label="Permalink to &quot;1.5 標示的讀法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>標示</th><th>意義</th></tr></thead><tbody><tr><td>● 必要</td><td>所有讀者都需要</td></tr><tr><td>○ 依情境</td><td>符合條件才讀, 條件寫在章首</td></tr><tr><td>◇ 進階或選讀</td><td>初階讀者可以略過</td></tr><tr><td>撰寫中 (僅有大綱)</td><td>只有章節骨架, 尚無可用內容</td></tr><tr><td>可閱讀 (部分資料待核對)</td><td>內容可參考, 但標示「待核對」的數字或來源尚未以第一手資料確認</td></tr><tr><td>已審閱</td><td>內容與來源經人工逐項核對</td></tr><tr><td>未實機驗證</td><td>指令依官方文件整理, 尚未在實機執行; 執行前請先在測試環境試跑</td></tr><tr><td>信心: 高 / 中 / 低</td><td>超出事實的判斷所附的信心水準; 標「推論」者為整理者推論</td></tr></tbody></table><p>正文只寫原則與判斷流程. 版本號, CVE, 價格與基準分數一律放在<a href="/docs-handbook-poc/ref/versions">參考資料</a>, 並標示來源與資料基準日.</p><h2 id="_1-6-各章完成度" tabindex="-1">1.6 各章完成度 <a class="header-anchor" href="#_1-6-各章完成度" aria-label="Permalink to &quot;1.6 各章完成度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章</th><th>狀態</th></tr></thead><tbody><tr><td>1, 3</td><td>可閱讀</td></tr><tr><td>2, 4, 6</td><td>撰寫中 (僅有大綱)</td></tr><tr><td>5, 7, 8</td><td>可閱讀 (指令未實機驗證)</td></tr><tr><td>9 至 14</td><td>可閱讀 (部分資料待核對)</td></tr><tr><td>15 至 17</td><td>撰寫中 (僅有大綱)</td></tr><tr><td>18, 19</td><td>可閱讀 (指令未實機驗證)</td></tr><tr><td>20</td><td>可閱讀 (部分資料待核對)</td></tr><tr><td>決策參考</td><td>可閱讀 (數字為試算框架, 非市場資料)</td></tr></tbody></table>',24)])])}const _=d(o,[["render",h]]);export{p as __pageData,_ as default};
